    """Fill (color 2) bg gaps of size <=2 between consecutive marker cells
    along any row/column, plus the background cells on the bounding-box
    perimeter of all marker cells. bg = most common color, marker = 2nd."""
    h, w = len(grid), len(grid[0])
    cnt = {}
    for r in grid:
        for x in r:
            cnt[x] = cnt.get(x, 0) + 1
    order = sorted(cnt, key=lambda x: -cnt[x])
    bg, mk = order[0], order[1]
    fill = 2
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mk]
    r0, r1 = min(p[0] for p in pts), max(p[0] for p in pts)
    c0, c1 = min(p[1] for p in pts), max(p[1] for p in pts)
    out = [r[:] for r in grid]

    def fl(r, c):
        if grid[r][c] == bg:
            out[r][c] = fill

    for r in range(h):
        idx = [c for c in range(w) if grid[r][c] == mk]
        for a, b in zip(idx, idx[1:]):
            if b - a - 1 <= 2:
                for c in range(a + 1, b):
                    fl(r, c)
    for c in range(w):
        idx = [r for r in range(h) if grid[r][c] == mk]
        for a, b in zip(idx, idx[1:]):
            if b - a - 1 <= 2:
                for r in range(a + 1, b):
                    fl(r, c)
    for c in range(c0, c1 + 1):
        fl(r0, c); fl(r1, c)
    for r in range(r0, r1 + 1):
